Core Catalog/Circulation Service Contain.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Core Catalog/Circulation Service Container container

Container_Boundary(core_catalog_circulation_service_container, "Core Catalog/Circulation Service Container") {
    Component(Domain_Models, "Domain Models", "Domain-Driven Design (DDD) Layers", "Encapsulates the business logic, entities, and value objects for library cataloging and circulation.")
    Component(Application_Services, "Application Services", "DDD Application Services", "Orchestrates use cases, coordinating domain models and infrastructure adapters.")
    Component(Infrastructure_Adapters, "Infrastructure Adapters", "Repository Pattern, Flyway/Liquibase, OpenAPI/Protobuf", "Manages persistence, database migrations on container startup, and external communication contracts.")
}

Rel(Application_Services, Domain_Models, "Executes business logic and workflows")
Rel(Application_Services, Infrastructure_Adapters, "Persists state and handles external messaging/caching")

@enduml

Search Engine Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Search Engine Container container

Container_Boundary(search_engine_container, "Search Engine Container") {
    Component(search_indexer_and_query_processor, "Search Indexer and Query Processor", "Dedicated Indexing Engine with ILM and Alias Swapping", "Handles real-time search queries, processes asynchronous catalogue update events, and manages zero-downtime schema migrations.")
    Component(cache_manager, "Cache Manager", "Redis Client", "Interacts with the Caching Container to optimize queries and cache facets.")
    Component(telemetry_exporter, "Telemetry Exporter", "W3C Trace Context / Telemetry Agent", "Exports scrubbed query telemetry and W3C Trace Context to the EU-Hosted Observability Infrastructure.")
}

Rel(search_indexer_and_query_processor, cache_manager, "Optimizes queries and caches facets", "Redis Protocol")
Rel(search_indexer_and_query_processor, telemetry_exporter, "Exports scrubbed query telemetry and W3C Trace Context", "W3C Trace Context")

@enduml

Caching Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Caching Container container

Container_Boundary("Caching Container", "Caching Container") {
    Component(InMemoryDataStore, "In-Memory Data Store", "Redis", "Provides low-latency, in-memory data storage, atomic operations, and automated eviction (allkeys-lru) with TTLs.")
    Component(CacheManagementandInvalidationController, "Cache Management and Invalidation Controller", "Redis Protocol", "Handles write invalidations, query optimizations, and distributed rate-limiting enforcement for incoming container requests.")
    Component(TelemetryForwarder, "Telemetry Forwarder", "Protocol Buffers / Compressed JSON", "Forwards telemetry, traces, and memory alerts to the EU-Hosted Observability Infrastructure.")
}

Rel(CacheManagementandInvalidationController, InMemoryDataStore, "Manages data storage, query optimization, and rate limiting using", "Redis Protocol")
Rel(CacheManagementandInvalidationController, TelemetryForwarder, "Feeds metrics and memory alerts to", "Internal")

@enduml

Message Broker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(message_broker_container, "Message Broker Container") {
    Component(Event_Broker_Core, "Event Broker Core", "Message Broker with Schema Registry (Avro/JSON Schema)", "Manages event-driven workflows, topic routing, and protocol validation.")
    Component(Dead_Letter_Queue_DLQ_Manager, "Dead Letter Queue (DLQ) Manager", "Message Broker DLQ Mechanism", "Captures and stores failed message deliveries for analysis and error handling.")
    Component(Trace_Propagation_Engine, "Trace Propagation Engine", "W3C Trace Context", "Propagates distributed tracing headers across asynchronous message flows.")
}

Rel(Event_Broker_Core, Dead_Letter_Queue_DLQ_Manager, "Routes unprocessable messages")
Rel(Event_Broker_Core, Trace_Propagation_Engine, "Injects and extracts trace contexts")

@enduml

Background Worker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Background Worker Container", "Background Worker Container") {
    Component(Asynchronous Job Processor, "Asynchronous Job Processor", "Idempotent Consumer Pattern & Dead Letter Queue (DLQ)", "Processes asynchronous workloads independently, preventing data corruption and quarantining persistently failing jobs.")
    Component(Telemetry Exporter, "Telemetry Exporter", "W3C Trace Context & Structured JSON Logging", "Exports runtime metrics and W3C trace context headers to the EU-Hosted Observability Infrastructure.")
    Component(External Communication Manager, "External Communication Manager", "Circuit Breaker & Backpressure", "Communicates with external systems utilizing rate-limiting, circuit breaker patterns, and backpressure to prevent cascading failures.")
    Component(Lifecycle Manager, "Lifecycle Manager", "Graceful Shutdown & Cancellation Tokens", "Intercepts SIGTERM signals and enforces hard timeouts to preserve task state during shutdowns.")
}

Rel(Asynchronous Job Processor, Telemetry Exporter, "Forwards trace context and structured logs")
Rel(Asynchronous Job Processor, External Communication Manager, "Invokes external systems via resilient patterns")

@enduml

Configuration and Secrets Management Con.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(config_secrets_container, "Configuration and Secrets Management Container") {
    Component(Configuration_Provider_Interface, "Configuration Provider Interface", "Standardized Configuration Provider Interface (Adapter Pattern)", "Decouples application code from the underlying secrets backend and handles dynamic runtime injection.")
    Component(Secrets_Management_Engine, "Secrets Management Engine", "HTTPS with X-Config-Version headers", "Manages secure access to secrets, ensuring immutable configuration versioning and compliance with EU data residency.")
